nginx_config:
daemon off;
master_process on;
worker_processes 4;
pid /tmp/aegisx-bench-nlkrl4vu/nginx.pid;
error_log /tmp/aegisx-bench-nlkrl4vu/nginx-error.log crit;
events { worker_connections 16384; multi_accept on; }
http {
    access_log off;
    client_body_temp_path /tmp/aegisx-bench-nlkrl4vu/body;
    proxy_temp_path /tmp/aegisx-bench-nlkrl4vu/proxy;
    keepalive_timeout 60s;
    keepalive_requests 100000;

    upstream origin { server 127.0.0.1:34319; keepalive 256; }
    server {
        listen 127.0.0.1:49565 reuseport;
        location / {
            root /tmp/aegisx-bench-nlkrl4vu/site;
            open_file_cache max=1000 inactive=60s;
            open_file_cache_valid 1s;
        }
    }
}
